local RoyalBannerHerald = {}
local PRODUCTS = {
    simple_linen_banner = { name = "Preprosta lanena zastava", linenCost = 2, threadCost = 1, woodCost = 1, time = 4, cost = 50, beauty = 20, prestige = 4, happiness = 1, description = "Preprosta lanena zastava za hišo." },
    painted_silk_banner = { name = "Poslikana svilena zastava", silkCost = 2, linenCost = 1, threadCost = 1, paintCost = 1, woodCost = 1, time = 7, cost = 160, beauty = 38, prestige = 10, happiness = 2, description = "Poslikana svilena zastava za trgovce." },
    silver_trimmed_banner = { name = "Srebrnoobrobljena zastava", silkCost = 2, silverCost = 1, linenCost = 1, threadCost = 1, paintCost = 1, woodCost = 1, time = 10, cost = 400, beauty = 52, prestige = 18, happiness = 3, description = "Srebrnoobrobljena zastava za plemiče." },
    gold_embroidered_banner = { name = "Zlato vezana zastava", silkCost = 3, goldCost = 1, silverCost = 1, linenCost = 1, threadCost = 1, paintCost = 1, woodCost = 1, time = 14, cost = 950, beauty = 68, prestige = 30, happiness = 4, description = "Zlato vezana zastava za visoke plemiče." },
    jewel_cornered_banner = { name = "Draguljakotna zastava", silkCost = 3, goldCost = 2, silverCost = 1, linenCost = 1, threadCost = 1, paintCost = 1, jewelCost = 1, time = 18, cost = 2100, beauty = 80, prestige = 45, happiness = 6, description = "Zastava z draguljnimi koti za visoko plemstvo." },
    royal_grand_heraldic_banner = { name = "Kraljevski velika grbovna zastava", silkCost = 5, goldCost = 3, silverCost = 2, linenCost = 2, threadCost = 2, paintCost = 2, jewelCost = 2, pearlCost = 2, time = 26, cost = 4800, beauty = 95, prestige = 72, happiness = 13, description = "Velika kraljevska grbovna zastava z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    banner_workshop = { name = "Zastavna delavnica", cost = { gold = 240, wood = 100, stone = 100, silk = 6, thread = 6 }, upkeep = 5, qualityBonus = 5 },
    heraldic_loft = { name = "Heraldikova podstrešje", cost = { gold = 880, wood = 240, stone = 240, silver = 6, paint = 6 }, upkeep = 20, qualityBonus = 18 },
    master_banner_atelier = { name = "Mojstrski zastavni atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_banner_palace = { name = "Kraljevska zastavna palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
RoyalBannerHerald.silkStock = 14; RoyalBannerHerald.linenStock = 12; RoyalBannerHerald.threadStock = 12; RoyalBannerHerald.paintStock = 10; RoyalBannerHerald.woodStock = 10; RoyalBannerHerald.silverStock = 6; RoyalBannerHerald.goldStock = 6; RoyalBannerHerald.jewelStock = 4; RoyalBannerHerald.pearlStock = 4
RoyalBannerHerald.productStock = {}; RoyalBannerHerald.buildings = {}; RoyalBannerHerald.maker = nil; RoyalBannerHerald.activeMaking = {}; RoyalBannerHerald.totalProducts = 0; RoyalBannerHerald.dayTimer = 0
function RoyalBannerHerald.init() RoyalBannerHerald.silkStock=14; RoyalBannerHerald.linenStock=12; RoyalBannerHerald.threadStock=12; RoyalBannerHerald.paintStock=10; RoyalBannerHerald.woodStock=10; RoyalBannerHerald.silverStock=6; RoyalBannerHerald.goldStock=6; RoyalBannerHerald.jewelStock=4; RoyalBannerHerald.pearlStock=4; RoyalBannerHerald.productStock={}; RoyalBannerHerald.buildings={}; RoyalBannerHerald.maker=nil; RoyalBannerHerald.activeMaking={}; RoyalBannerHerald.totalProducts=0; RoyalBannerHerald.dayTimer=0; print("[RoyalBannerHerald] Royal Banner Herald System initialized (6 products, 4 buildings)") end
function RoyalBannerHerald.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; RoyalBannerHerald.maker={name=n or ("Zastavar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zastavar najet: %s (spretnost: %d)",RoyalBannerHerald.maker.name,s),"success") end; return true end
function RoyalBannerHerald.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function RoyalBannerHerald.build(id) local ok,e=RoyalBannerHerald.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(RoyalBannerHerald.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function RoyalBannerHerald.getQualityBonus() local b=0; for _,bd in ipairs(RoyalBannerHerald.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function RoyalBannerHerald.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.silkCost and RoyalBannerHerald.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.linenCost and RoyalBannerHerald.linenStock<(d.linenCost or 0) then return false,"Premalo lanu" end; if d.threadCost and RoyalBannerHerald.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.paintCost and RoyalBannerHerald.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.woodCost and RoyalBannerHerald.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and RoyalBannerHerald.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and RoyalBannerHerald.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and RoyalBannerHerald.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and RoyalBannerHerald.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #RoyalBannerHerald.buildings==0 then return false,"Potrebna zastavna delavnica" end; if not RoyalBannerHerald.maker then return false,"Potreben zastavar" end; return true end
function RoyalBannerHerald.make(pt,qty) qty=qty or 1; local ok,e=RoyalBannerHerald.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.silkCost then RoyalBannerHerald.silkStock=RoyalBannerHerald.silkStock-d.silkCost*qty end; if d.linenCost then RoyalBannerHerald.linenStock=RoyalBannerHerald.linenStock-d.linenCost*qty end; if d.threadCost then RoyalBannerHerald.threadStock=RoyalBannerHerald.threadStock-d.threadCost*qty end; if d.paintCost then RoyalBannerHerald.paintStock=RoyalBannerHerald.paintStock-d.paintCost*qty end; if d.woodCost then RoyalBannerHerald.woodStock=RoyalBannerHerald.woodStock-d.woodCost*qty end; if d.silverCost then RoyalBannerHerald.silverStock=RoyalBannerHerald.silverStock-d.silverCost*qty end; if d.goldCost then RoyalBannerHerald.goldStock=RoyalBannerHerald.goldStock-d.goldCost*qty end; if d.jewelCost then RoyalBannerHerald.jewelStock=RoyalBannerHerald.jewelStock-d.jewelCost*qty end; if d.pearlCost then RoyalBannerHerald.pearlStock=RoyalBannerHerald.pearlStock-d.pearlCost*qty end; local t=d.time; if RoyalBannerHerald.maker then t=math.max(1,t-math.floor(RoyalBannerHerald.maker.skill/12)) end; table.insert(RoyalBannerHerald.activeMaking,{id="banner_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šivanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function RoyalBannerHerald.completeMaking(m) local q=1.0+(RoyalBannerHerald.getQualityBonus()/100); if RoyalBannerHerald.maker then q=q+(RoyalBannerHerald.maker.skill/140) end; q=math.min(2.5,q); RoyalBannerHerald.productStock[m.productType]=(RoyalBannerHerald.productStock[m.productType] or 0)+m.quantity; RoyalBannerHerald.totalProducts=RoyalBannerHerald.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if RoyalBannerHerald.maker then RoyalBannerHerald.maker.itemsMade=RoyalBannerHerald.maker.itemsMade+m.quantity; if math.random()<0.25 then RoyalBannerHerald.maker.skill=math.min(100,RoyalBannerHerald.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zastava izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"banner.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function RoyalBannerHerald.update(dt) if not _G.state then return end; RoyalBannerHerald.dayTimer=RoyalBannerHerald.dayTimer+dt; if RoyalBannerHerald.dayTimer>=30 then RoyalBannerHerald.dayTimer=0; for i=#RoyalBannerHerald.activeMaking,1,-1 do local m=RoyalBannerHerald.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then RoyalBannerHerald.completeMaking(m); table.remove(RoyalBannerHerald.activeMaking,i) end end; local tu=0; for _,bd in ipairs(RoyalBannerHerald.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if RoyalBannerHerald.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function RoyalBannerHerald.getStats() return {silkStock=RoyalBannerHerald.silkStock,linenStock=RoyalBannerHerald.linenStock,threadStock=RoyalBannerHerald.threadStock,paintStock=RoyalBannerHerald.paintStock,woodStock=RoyalBannerHerald.woodStock,silverStock=RoyalBannerHerald.silverStock,goldStock=RoyalBannerHerald.goldStock,jewelStock=RoyalBannerHerald.jewelStock,pearlStock=RoyalBannerHerald.pearlStock,productStock=RoyalBannerHerald.productStock,numBuildings=#RoyalBannerHerald.buildings,hasMaker=RoyalBannerHerald.maker~=nil,makerName=RoyalBannerHerald.maker and RoyalBannerHerald.maker.name or "—",makerSkill=RoyalBannerHerald.maker and RoyalBannerHerald.maker.skill or 0,activeMaking=#RoyalBannerHerald.activeMaking,totalProducts=RoyalBannerHerald.totalProducts} end
return RoyalBannerHerald
